/** Config-level orchestration for one selected application's authored design. */
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { assemblyBehind } from "../boundary/assembly/assembly-registry.js";
import { formatConceptSpecDiagnostic, parseSpec, specificationsAreCompatible, specificationSourceDigest, } from "../reactions/concepts/concept-spec.js";
import { canonicalDigest } from "../utils/canonical-json.js";
import { isDesignIdentifier } from "../utils/design-identifiers.js";
import { ordinal } from "../utils/ordinal.js";
import { parseApplicationDesignDocument, validateAuthoredApplicationDesign, } from "./authored-application-design.js";
import { scanDesignMarkdown } from "./markdown-design-source.js";
function issueOrder(left, right) {
    const leftLocation = left.location;
    const rightLocation = right.location;
    if (leftLocation !== undefined || rightLocation !== undefined) {
        if (leftLocation === undefined)
            return 1;
        if (rightLocation === undefined)
            return -1;
        const source = ordinal(leftLocation.source, rightLocation.source);
        if (source !== 0)
            return source;
        if (leftLocation.line !== rightLocation.line)
            return leftLocation.line - rightLocation.line;
        if (leftLocation.column !== rightLocation.column)
            return leftLocation.column - rightLocation.column;
    }
    const priority = (code) => code === "MIXED_BINDING_PLACEMENT"
        ? 0
        : code === "DUPLICATE_EXTERNAL_BINDING"
            ? 1
            : code === "MISSING_EXTERNAL_BINDING"
                ? 3
                : 2;
    const codeOrder = priority(left.code) - priority(right.code);
    if (codeOrder !== 0)
        return codeOrder;
    return ordinal(`${left.code}\0${left.message}`, `${right.code}\0${right.message}`);
}
export class AuthoredDesignCheckError extends Error {
    issues;
    constructor(issues) {
        const ordered = [...issues].sort(issueOrder);
        super(`authored application design has ${ordered.length} issue${ordered.length === 1 ? "" : "s"}:\n` +
            ordered
                .map(({ code, message, location }) => {
                const at = location === undefined
                    ? ""
                    : `${location.source}:${location.line}:${location.column}: `;
                return `- ${at}[${code}] ${message}`;
            })
                .join("\n"));
        this.name = "AuthoredDesignCheckError";
        this.issues = ordered;
    }
}
function localPath(url, label) {
    if (!(url instanceof URL) || url.protocol !== "file:") {
        const protocol = url instanceof URL ? url.protocol : "non-URL value";
        throw new Error(`authored design: ${label} must be a local file URL, not ${protocol}.`);
    }
    return fileURLToPath(url);
}
async function loadSource(url, label) {
    const path = localPath(url, label);
    const scanned = scanDesignMarkdown(await readFile(path, "utf8"), path);
    return {
        url,
        path,
        content: scanned.content,
        digest: scanned.digest,
        lines: scanned.lines,
    };
}
async function loadRegistration(registration) {
    const entries = registration.documents.map((url, index) => ({
        url,
        label: `design.documents[${index}]`,
    }));
    const paths = new Map();
    for (const entry of entries) {
        const path = localPath(entry.url, entry.label);
        const previous = paths.get(path);
        if (previous !== undefined) {
            throw new Error(`authored design: ${entry.label} duplicates ${previous}: ${path}.`);
        }
        paths.set(path, entry.label);
    }
    // There is exactly one readFile call for every validated, distinct local URL.
    return Promise.all(entries.map((entry) => loadSource(entry.url, entry.label)));
}
function withoutLocations(specification) {
    return JSON.parse(JSON.stringify(specification, (key, value) => (key === "location" ? undefined : value)));
}
function coverageOf(selected, corpus) {
    const entries = [];
    for (const endpoint of selected.endpoints) {
        entries.push({
            kind: "endpoint",
            identity: endpoint.identity,
            locations: corpus
                .flatMap(({ endpoints }) => endpoints)
                .filter(({ identity }) => identity === endpoint.identity)
                .map(({ location }) => location),
        });
    }
    for (const [kind, identities] of [
        ["reaction", selected.reactions],
        ["view", selected.views],
        ["former", selected.formers],
    ]) {
        for (const identity of identities) {
            entries.push({
                kind,
                identity,
                locations: corpus
                    .flatMap(({ links }) => links)
                    .filter((link) => link.kind === kind && link.target === identity)
                    .map(({ location }) => location),
            });
        }
    }
    for (const computation of selected.computations) {
        const declarations = corpus.flatMap(({ computations }) => computations);
        const links = corpus.flatMap(({ links }) => links);
        entries.push({
            kind: "computation",
            identity: computation.name,
            locations: [
                ...declarations
                    .filter(({ name }) => name === computation.name)
                    .map(({ location }) => location),
                ...links
                    .filter(({ kind, target }) => kind === "computation" && target === computation.name)
                    .map(({ location }) => location),
            ].sort((left, right) => issueOrder({ code: "MISSING_COVERAGE", message: "", location: left }, { code: "MISSING_COVERAGE", message: "", location: right })),
        });
    }
    return entries;
}
/** Load, parse, select, and check the authored design for exactly one assembly. */
export async function checkAuthoredDesign(options) {
    const designSources = await loadRegistration(options.design);
    const documents = designSources.map((source) => parseApplicationDesignDocument(source.content, source.path));
    const assembled = assemblyBehind(options.assembly);
    const declarations = assembled.authoredDeclarations;
    const executableComputations = assembled.computations
        .filter(({ source }) => source === "vocabulary")
        .map(({ name }) => ({ name }))
        .sort((left, right) => ordinal(left.name, right.name));
    const analyzed = options.resolveComputationInputs === undefined
        ? []
        : await options.resolveComputationInputs({
            assembly: options.assembly,
            computations: executableComputations,
        });
    const analyzedNames = new Set();
    const executableNames = new Set(executableComputations.map(({ name }) => name));
    for (const item of analyzed) {
        if (analyzedNames.has(item.name)) {
            throw new Error(`authored design: computation input adapter returned ${JSON.stringify(item.name)} more than once.`);
        }
        if (!executableNames.has(item.name)) {
            throw new Error(`authored design: computation input adapter returned unselected computation ${JSON.stringify(item.name)}.`);
        }
        analyzedNames.add(item.name);
    }
    const inputsByComputation = new Map(analyzed.map(({ name, inputs }) => [name, inputs]));
    const concepts = [];
    const unresolvedConceptInstances = [];
    const orchestrationIssues = [];
    for (const inventory of assembled.engine
        .exportConcepts()
        .filter(({ name }) => name !== "RequestBoundary")
        .sort((left, right) => ordinal(left.name, right.name))) {
        if (inventory.specification === undefined) {
            unresolvedConceptInstances.push(inventory.name);
            orchestrationIssues.push({
                code: "MISSING_CONCEPT_SPECIFICATION",
                message: `selected concept instance ${JSON.stringify(inventory.name)} has no authored concept specification.`,
            });
            continue;
        }
        const ownedTypes = await options.resolveOwnedTypeNames?.({
            instance: inventory.name,
            definition: inventory.specification.definitionName,
            specification: inventory.specification,
        });
        if (ownedTypes !== undefined &&
            (new Set(ownedTypes).size !== ownedTypes.length ||
                ownedTypes.some((name) => !isDesignIdentifier(name)))) {
            throw new Error(`authored design: owned-type adapter returned duplicate or invalid names for ${JSON.stringify(inventory.name)}.`);
        }
        concepts.push({
            instance: inventory.name,
            definition: inventory.specification.definitionName,
            externalParameters: inventory.specification.externalTypes
                .map(({ name }) => name)
                .sort(ordinal),
            ...(ownedTypes === undefined ? {} : { ownedTypes: [...ownedTypes].sort(ordinal) }),
            specification: inventory.specification,
        });
    }
    const sharedDefinitions = [];
    const byDefinition = Map.groupBy(concepts, ({ definition }) => definition);
    for (const [definition, instances] of [...byDefinition].sort(([left], [right]) => ordinal(left, right))) {
        const canonical = instances[0].specification;
        if (instances.some(({ specification }) => !specificationsAreCompatible(canonical, specification))) {
            orchestrationIssues.push({
                code: "INCOMPATIBLE_SHARED_DEFINITION",
                message: `selected instances ${instances.map(({ instance }) => JSON.stringify(instance)).join(", ")} use incompatible specifications for definition ${JSON.stringify(definition)}.`,
            });
            continue;
        }
        sharedDefinitions.push({
            definition,
            instances: instances.map(({ instance }) => instance).sort(ordinal),
            specificationDigest: canonicalDigest(withoutLocations(canonical)),
            canonicallyEqual: true,
        });
    }
    let conceptSources;
    if (options.conceptSources !== undefined) {
        const supplied = new Map();
        for (const source of options.conceptSources) {
            if (supplied.has(source.instance)) {
                throw new Error(`authored design: concept source adapter returned ${JSON.stringify(source.instance)} more than once.`);
            }
            supplied.set(source.instance, source);
        }
        conceptSources = concepts.map(({ instance, definition, specification }) => {
            const source = supplied.get(instance);
            if (source === undefined) {
                throw new Error(`authored design: concept source adapter omitted selected instance ${JSON.stringify(instance)}.`);
            }
            const path = localPath(source.url, `conceptSources[${JSON.stringify(instance)}].url`);
            const scanned = scanDesignMarkdown(source.content, path);
            const parsed = parseSpec(scanned.content);
            if (parsed.specification === undefined) {
                throw new Error(`authored design: traced concept source for ${JSON.stringify(instance)} is invalid:\n${parsed.diagnostics.map(formatConceptSpecDiagnostic).join("\n")}`);
            }
            if (scanned.digest !== specificationSourceDigest(specification)) {
                throw new Error(`authored design: traced concept source for ${JSON.stringify(instance)} does not exactly match its registered spec text.`);
            }
            return {
                instance,
                definition,
                definitionLine: scanned.headings.find(({ level }) => level === 1)?.location.line ?? 1,
                url: source.url,
                path,
                content: scanned.content,
                digest: scanned.digest,
                lines: scanned.lines,
            };
        });
        const selectedNames = new Set(concepts.map(({ instance }) => instance));
        const extra = options.conceptSources.find(({ instance }) => !selectedNames.has(instance));
        if (extra !== undefined) {
            throw new Error(`authored design: concept source adapter supplied unselected instance ${JSON.stringify(extra.instance)}.`);
        }
    }
    const selected = {
        reactions: declarations
            .filter(({ kind }) => kind === "reaction")
            .map(({ identity }) => identity)
            .sort(ordinal),
        endpoints: assembled.endpoints
            .map(({ name: identity, path }) => ({ identity, path }))
            .sort((left, right) => ordinal(left.identity, right.identity)),
        views: declarations
            .filter(({ kind }) => kind === "view")
            .map(({ identity }) => identity)
            .sort(ordinal),
        formers: declarations
            .filter(({ kind }) => kind === "former")
            .map(({ identity }) => identity)
            .sort(ordinal),
        computations: executableComputations.map(({ name }) => ({
            name,
            ...(inputsByComputation.has(name) ? { inputs: inputsByComputation.get(name) } : {}),
        })),
        concepts: concepts.map(({ instance, definition, externalParameters, ownedTypes }) => ({
            instance,
            definition,
            externalTypes: externalParameters,
            ...(ownedTypes === undefined ? {} : { ownedTypes }),
        })),
        ...(unresolvedConceptInstances.length === 0
            ? {}
            : { unresolvedConceptInstances: unresolvedConceptInstances.sort(ordinal) }),
    };
    const validationIssues = validateAuthoredApplicationDesign(documents, selected);
    const issues = [...orchestrationIssues, ...validationIssues];
    if (issues.length > 0)
        throw new AuthoredDesignCheckError(issues);
    return {
        sources: {
            documents: designSources,
            ...(conceptSources === undefined ? {} : { concepts: conceptSources }),
        },
        documents,
        declarations,
        selected,
        concepts,
        sharedDefinitions,
        coverage: coverageOf(selected, documents),
        computationInputValidation: executableComputations.map(({ name }) => ({
            name,
            status: inputsByComputation.has(name) ? "validated" : "not-claimed",
        })),
    };
}
